export const DATA_01: ReadingTest[] = [
  { id: "rd-001", num: 1, title: "Đề 001", timeMin: 60, parts: [
    { title: "The Impact of Social Media on Daily Life", paragraphs: ["Over the past two decades, social media has quietly reshaped how people communicate, work, and relax. Platforms such as Facebook, Instagram, and TikTok now reach billions of users worldwide, and for many people, checking a phone first thing in the morning has become an automatic habit. What began as a simple way to stay in touch with friends has grown into a powerful tool that shapes opinions and spreads news across the world. Because it is so deeply woven into everyday routines, it is worth asking how this constant connection actually affects ordinary life.", "One clear benefit is that social media makes staying connected easier than ever before. Grandparents living far away can watch video clips of grandchildren growing up, and old classmates can reconnect after years apart with nothing more than a single friendly message. Beyond personal relationships, these platforms also give ordinary users quick and often free access to breaking news, practical health advice, and job openings that they might otherwise never come across. During emergencies such as storms or floods, local groups often share warnings faster than official channels can. For people in remote areas, this instant access to information can be genuinely life-changing.", "At the same time, many researchers warn that heavy use of social media brings real costs. Surveys suggest that some teenagers spend more than four hours a day scrolling through short videos and photos, time that could otherwise go toward homework, sleep, or outdoor exercise. Constant exposure to carefully edited images of other people's lives can also make ordinary users feel that their own lives are somehow lacking. Some doctors have linked heavy use of these apps to higher levels of anxiety, poor sleep, and low self-esteem, especially among younger users who compare themselves to online influencers.", "Social media has also quietly changed the way people talk to one another. Short comments, emojis, and quick reactions increasingly replace longer phone calls or face-to-face conversations, even between close family members living under the same roof. Some sociologists argue that this shift makes communication faster but shallower , since a heart emoji rarely carries the same warmth as a real conversation. Others counter that these small daily exchanges, taken together, actually help relationships survive busy modern schedules that once caused people to drift apart.", "Most experts agree that the real problem is not social media itself but how it is used. Turning off notifications during work hours, setting a firm daily time limit, and choosing face-to-face meetings over messaging can help people enjoy real benefits without being quietly controlled. In the end, social media is simply a tool, and its impact on daily life depends largely on the hand that holds it."], questions: [{ q: "According to the passage, how can grandparents who live far away stay close to their grandchildren?", options: ["By reconnecting with old classmates after years apart", "By following brief video updates as the youngsters keep growing", "By exchanging detailed letters mailed to them each month", "By visiting them in person every holiday"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Social media mainly helps distant family members stay in touch", "Social media causes far more psychological harm than any real benefit", "Social media has now completely replaced ordinary face-to-face communication for everyone", "Social media brings real benefits but also carries real risks for users"], answer: 3 }, { q: "The word \"reshaped\" in paragraph 1 is closest in meaning to _______.", options: ["transformed", "replaced", "connected", "restored"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a possible negative effect of heavy social media use?", options: ["increased anxiety and lower self-esteem among teens", "reduced sleep quality and amount for many users", "noticeably lower grades in school subjects", "shallower daily talks between close family members"], answer: 2 }, { q: "According to the passage, why can local social media groups be especially helpful during emergencies such as storms or floods?", options: ["They often warn people faster than official channels can", "They coordinate rescue efforts directly with government teams", "They also give ordinary users breaking news and job openings", "They provide free transportation to emergency shelters"], answer: 0 }, { q: "The phrase \"these platforms\" in paragraph 2 refers to _______.", options: ["grandparents and old classmates", "video clips of grandchildren", "breaking news and jobs", "Facebook, Instagram, and TikTok"], answer: 3 }, { q: "What can be inferred from the passage about the effect of emojis and quick reactions on family relationships?", options: ["Grandparents can now watch video clips of their grandchildren growing up", "Not all experts agree on whether these changes help families", "Older sociologists mostly believe these changes have ruined communication entirely", "Weaker family bonds have caused some people to send more emojis"], answer: 1 }, { q: "The word \"shallower\" in paragraph 4 is closest in meaning to _______.", options: ["empty", "distant", "superficial", "narrow"], answer: 2 }, { q: "According to the passage, how much time do some teenagers reportedly spend scrolling through short videos and photos each day?", options: ["Over four hours on a typical school day", "Over two hours each day during a typical school week", "Nearly six hours on an average school day usually", "About four hours during typical school weekdays"], answer: 0 }, { q: "What is the author's main purpose in writing this passage?", options: ["To warn readers specifically about teenagers' declining mental health", "To persuade readers that everyone should quit social media completely", "To criticize technology companies for creating deliberately addictive apps", "To explain both the benefits and the drawbacks of social media"], answer: 3 }] },
    { title: "Phuong Sweet Soup: A Culinary Tradition", paragraphs: ["Long before refrigerators and supermarkets reshaped Vietnamese kitchens, sweet soups known as che had already earned a quiet place in the country's culinary identity. Sold from roadside carts, market stalls, and family-run shops alike, these dessert soups combine beans, fruit, tapioca pearls, and coconut milk into a dish that is at once humble and endlessly adaptable. One style associated with the city of Hue is often singled out for special praise. Food writers argue that its restrained sweetness sets it apart from bolder, sugar-heavy versions found elsewhere in the country.", "What distinguishes this style is not any single exotic ingredient but the discipline with which ordinary ones are combined. Mung beans, lotus seeds, and black-eyed peas are cooked separately and timed precisely so that none turns mushy, before being reunited in a lightly sweetened broth. Coconut cream is drizzled on top only at the moment of serving, never stirred in beforehand, so its richness stays distinct rather than dissolving into the broth. This insistence on separation, rather than blending, is often cited as the dish's defining technical signature.", "Historically, this style traces back to the former imperial court in Hue. Cooks there prepared delicate variations to satisfy royal palates that had grown tired of anything too plain, and court chefs reportedly competed to create ever more refined combinations. Several respected recipes today are said to descend, at least loosely, from dishes first served within palace walls generations ago. Such origin stories, however, cannot always be verified, yet food historians note that surviving techniques closely match written accounts of formal court dining, lending the claims real credibility.", "Making these desserts well is widely regarded as more demanding than it first appears. Because no single ingredient should dominate, the cook must judge each component's cooking time and adjust sugar in small increments so the beans or fruit underneath are never masked. Older cooks often say that a bowl reveals its maker's patience long before it reveals any recipe, since rushing a single step tends to unbalance the final result. A genuinely well-made version, rather than one merely following instructions, is therefore considered a marker of real culinary skill.", "In recent years, this style has moved well beyond its home region. It now appears on dessert menus in major cities and draws tourists eager for something more restrained than typical street sweets. Some restaurants advertise their bowls as traditional, although critics note that certain renditions add condensed milk or extra sugar, shifting the dish toward the very sweetness the original style was designed to avoid. This tension between commercial appeal and authenticity is not unique to Vietnamese food, but it does suggest that even an old dish must negotiate its identity as it reaches unfamiliar audiences.", "This tension raises a genuine question for those who study regional food culture. Whether it will preserve the dish's character or gradually erode it remains unresolved among researchers. Yet its presence on modern menus, however transformed, reflects a lasting appetite for a tradition whose value lies less in novelty than in the quiet discipline behind its preparation."], questions: [{ q: "What is the main idea of the passage?", options: ["Careful technique defines a dessert tradition now facing pressure to change", "The recipe for coconut cream topping requires very precise timing", "Modern commercial demand matters more than the dish's original technique", "This dessert has completely lost its original identity in modern cities"], answer: 0 }, { q: "According to the passage, why is coconut cream added only at the moment of serving rather than earlier?", options: ["So that it keeps the soup from cooling down too quickly", "So that the beans absorb its flavor more evenly", "So that none of the beans turns mushy during the cooking process", "So that its richness always stays separate from the broth"], answer: 3 }, { q: "The word \"discipline\" in paragraph 2 is closest in meaning to _______.", options: ["obedience", "devotion", "rigor", "tradition"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of what makes this dessert style distinctive?", options: ["cooking absolutely every ingredient in its own separate pot", "using ingredients grown only in the Hue region", "adding coconut cream only at the moment of serving", "using recipes said to descend from the imperial court"], answer: 1 }, { q: "According to the passage, what do food historians note about the surviving techniques of this dessert style?", options: ["They exactly match every modern restaurant recipe sold now in Vietnam", "They were only written down for the very first time", "These old techniques correspond well with recorded court dining", "Such origin stories, however, cannot always be verified"], answer: 2 }, { q: "The word \"its\" in paragraph 1 refers to _______.", options: ["the city of Hue", "an adaptable dish", "the coconut milk", "the Hue style"], answer: 3 }, { q: "What can be inferred from the passage about the future of this dessert tradition?", options: ["Its future character may depend on how commercial pressures are handled", "Food researchers have already concluded the tradition will disappear within a generation", "Growing tourist demand has caused restaurants to preserve the original recipe faithfully", "Court chefs once competed to create the most refined combinations"], answer: 0 }, { q: "The word \"erode\" in paragraph 6 is closest in meaning to _______.", options: ["destroy", "diminish", "modernize", "erase"], answer: 1 }, { q: "According to the passage, how do some newer restaurant versions of this dessert differ from the traditional style?", options: ["They tend to remove the coconut cream topping entirely", "They typically replace the beans with fresh tropical fruit", "They advertise their bowls as traditional", "They tend to include extra sugar or condensed milk"], answer: 3 }, { q: "What is the author's main purpose in writing this passage?", options: ["To give precise cooking instructions for making this dessert at home", "To argue that imperial court history is the dish's only value", "To describe the technique and evolving identity of a dessert", "To criticize modern restaurants for abandoning authentic recipes"], answer: 2 }] },
    { title: "The Symbiosis of Mental and Physical Health", paragraphs: ["For much of modern medical history, mental and physical health were treated as largely separate domains, each assigned to its own specialists, its own vocabulary, and its own diagnostic criteria. A patient with a broken bone rarely consulted a psychiatrist, just as someone struggling with depression was seldom referred for a cardiovascular workup. Yet a growing body of research has begun to erode this tidy separation. It reveals instead a densely interwoven relationship in which the mind and body continuously shape one another. Often the connection resists easy categorization as purely psychological or purely physiological.", "Cortisol is normally released in brief, useful bursts that help the body respond to short-term threats. When the hormone instead remains elevated for weeks or months, several markers of immune function measurably decline, leaving the body more susceptible to everything from the common cold to slower wound healing. What makes this finding significant is not merely that stress feels unpleasant, but that a psychological state, sustained over time, can leave a biochemical signature detectable in blood tests months later.", "A second, perhaps less intuitive connection between mind and body runs through the gut itself. Trillions of bacteria residing in the digestive tract communicate with the brain along the vagus nerve and through the production of neurotransmitter precursors, a relationship researchers have labeled the gut-brain axis. Disruptions to this microbial community have been linked, in various animal and preliminary human studies, to anxiety-like behavior and altered mood. While the precise mechanisms remain contested , the correlation is strong enough that several major medical centers now include dietary assessment in mental health evaluations.", "The relationship, however, does not run in only one direction. Individuals diagnosed with chronic physical conditions such as diabetes or heart disease develop clinical depression at roughly twice the rate of the general population. This elevated risk persists even after controlling for the burden of managing a difficult illness. Some researchers now suspect that the inflammatory processes underlying many chronic diseases may themselves alter brain chemistry directly, rather than depression arising purely as an emotional reaction to diagnosis.", "Exercise and sleep sit at a particularly interesting intersection, since each functions simultaneously as cause and consequence within this system. Regular physical activity reliably improves mood and strengthens immune markers, yet depression itself often saps the very motivation a person needs to exercise in the first place. Insomnia, meanwhile, frequently accompanies both anxiety and inflammatory illness. The resulting feedback loops can be difficult to interrupt from either the psychological or the physical side alone.", "None of this evidence is as clean as popular summaries sometimes suggest. [1] Much of the underlying research is correlational, and disentangling cause from effect in a system with so many feedback loops remains genuinely difficult. [2] A person who exercises less might simply feel unwell for reasons unrelated to any biochemical pathway. [3] Even so, the cumulative weight of findings across such different methodologies, from hormone assays to microbiome sequencing, has pushed clinicians toward treatment models that address mind and body together. [4] The exact mechanisms connecting the two , however, remain only partially mapped."], questions: [{ q: "What is the main idea of the passage?", options: ["Chronic stress is presented as the main cause of most physical illness", "Mind and body shape one another in ways still only partly understood", "Scientists have now supposedly mapped fully how mental and physical health interact", "Physical illness is said to cause psychological problems more often than reversed"], answer: 1 }, { q: "According to the passage, under what circumstance does cortisol appear to impair immune function?", options: ["When it stays high for a long stretch instead of returning quickly", "Whenever a person experiences even a brief spell of quite ordinary nervousness", "When cortisol rises suddenly during one stressful event, weakening the immune system", "In brief, useful bursts that help the body respond to short-term threats"], answer: 0 }, { q: "The word \"contested\" in paragraph 3 is closest in meaning to _______.", options: ["disproven", "researched", "disputed", "blocked"], answer: 2 }, { q: "According to the passage, which of the following is NOT identified as a documented link between mental and physical health?", options: ["gut bacteria communicate with the brain via the vagus nerve", "elevated cortisol is associated with weaker immune markers", "chronic illness always causes depression in every single patient", "improving gut bacteria alone can cure clinical depression"], answer: 3 }, { q: "According to the passage, why do researchers suspect that inflammation itself, not just diagnosis, may explain higher depression rates among chronically ill patients?", options: ["The heightened risk remains even when the burden of illness is accounted for", "Doctors often fail to diagnose depression in physically ill patients early enough", "Diabetes and heart disease patients develop depression at twice the usual rate", "Chronic illness naturally makes people feel hopeless, which directly alters their brain chemistry"], answer: 0 }, { q: "The phrase \"the two\" in paragraph 6 refers to _______.", options: ["hormone assays and sequencing", "mind and body", "clinicians and treatment models", "cause and effect"], answer: 1 }, { q: "What does the passage imply about how confident researchers can be that stress directly causes immune decline?", options: ["The correlational evidence overall means clinicians have abandoned combined treatment models", "Weakened immune systems have been shown to directly cause cortisol levels", "Gut bacteria communicate with the brain through the vagus nerve", "Researchers remain reasonably confident despite lacking fully isolated proof"], answer: 3 }, { q: "The word \"susceptible\" in paragraph 2 is closest in meaning to _______.", options: ["sensitive", "resistant", "prone", "doubtful"], answer: 2 }, { q: "What is the author's main purpose in writing this passage?", options: ["To present growing evidence that mental and physical health are deeply interconnected", "To argue that psychiatric medication should be replaced by dietary treatment", "To prove definitively that stress alone causes most chronic illnesses", "To explain precisely how cortisol damages the immune system over time"], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Sleep deprivation, for instance, provides an equally clear example of this same difficulty.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "The Enigma of Easter Island: Ecocide or Resilience?", paragraphs: ["Rapa Nui, the remote Pacific island Europeans later named Easter Island, has for decades served less as a place than as a parable. In the popular telling, a thriving Polynesian society felled its own forests to move enormous stone statues. This act triggered ecological collapse and ultimately destroyed the society from within, well before any European ever set foot on its shores. Not only does this narrative offer a tidy moral about self-destruction, but it has also been invoked repeatedly, in books and documentaries alike, as a cautionary tale for the planet as a whole.", "A competing account emerged in the early 2000s that questioned nearly every load-bearing assumption of the original story. Archaeologists Terry Hunt and Carl Lipo examined radiocarbon dates from multiple excavation sites across the island. They argued that permanent settlement likely began several centuries later than earlier estimates had assumed. This later starting point would leave a far narrower window in which any population boom, resource strain, and subsequent societal collapse could all plausibly have occurred. If their revised chronology holds, much of the timeline underpinning the collapse narrative would need to be compressed or abandoned altogether.", "Deforestation itself is not seriously disputed, since sediment cores confirm that the island's palm forests vanished within a few centuries of human arrival. [1] What remains genuinely contested is the cause. [2] The traditional account attributes the loss mainly to land clearance and to logging used for moving the massive statues. [3] Hunt and Lipo instead emphasize the Polynesian rat, an unintentional stowaway on colonizing canoes, whose population could have exploded rapidly in a predator-free environment lacking any natural check. [4] These rats, on this account, consumed palm seeds faster than the trees could ever reproduce. Even the revisionists concede that human activity likely compounded whatever damage the rats initiated.", "Skeletal evidence has not yielded the widespread signs of famine that a genuine societal collapse would be expected to leave behind. Isotope analysis of human remains suggests a diet that narrowed noticeably after deforestation took hold. Yet it never collapsed into the crisis-level malnutrition that the ecocide narrative implies should have followed across the wider population. This does not necessarily mean daily life continued entirely unaffected, since a narrowed diet still represents real and sustained hardship for a small, resource-limited island population. It does suggest, however, that some form of adaptation allowed the population to persist rather than to catastrophically implode as the popular narrative claims.", "Population figures at first European contact in 1722 are themselves disputed within a fairly narrow range. The number that collapsed afterward, however, is not seriously in question among historians. Within roughly a century, introduced disease, Peruvian slave raids that forcibly removed islanders, and the disruptions of colonial administration reduced the population far more severely than anything the pre-contact archaeological record indicates. Some historians therefore argue that the decline was overwhelmingly a colonial-era phenomenon rather than a pre-contact ecological one. This reframing, though, does not by itself resolve how severe the earlier resource pressures actually were.", "None of this amounts to a simple exoneration of pre-contact islanders. Nor does it fully vindicate the revisionist account, since the revised settlement chronology remains actively debated within the field. What the newer evidence does suggest, cumulatively, is that the moai-building society was considerably more adaptive, and its trajectory considerably less linear, than the tidy self-destruction narrative allows. The island's history may ultimately turn out to be less a fable about ecological suicide than a case study in how quickly a compelling story can outrun the evidence that first supported it."], questions: [{ q: "What is the main idea of the passage?", options: ["The traditional collapse story is being reconsidered though key evidence remains unsettled", "The traditional collapse story has now been thoroughly disproven by newer evidence", "A few minor details of the traditional collapse story are mildly disputed", "New evidence proves the revisionist account correct and the traditional one false"], answer: 0 }, { q: "According to the passage, what would be the consequence if Hunt and Lipo's revised settlement chronology is accurate?", options: ["The traditional collapse timeline has definitely been proven wrong by their chronology", "All previous archaeological research on Rapa Nui would become entirely worthless", "Much of the traditional collapse timeline would need to be shortened or dropped", "Radiocarbon dates from multiple excavation sites were examined across the island"], answer: 2 }, { q: "The word \"load-bearing\" in paragraph 2 is closest in meaning to _______.", options: ["additional", "essential", "cautionary", "burdensome"], answer: 1 }, { q: "According to the passage, which of the following is NOT presented as a factor in the population decline that followed European contact?", options: ["the complete extermination of the whole population by disease", "Peruvian slave raids that forcibly removed many islanders", "disruptions caused by the colonial administration system", "a renewed ecological collapse from overpopulation"], answer: 3 }, { q: "According to the passage, what does the absence of widespread signs of famine in skeletal remains suggest about life on the island after deforestation?", options: ["Life on the island continued completely unaffected by the changing food supply", "Some adaptation likely let the population continue despite real hardship", "The narrowed diet directly caused the population's later disease-driven collapse", "Isotope analysis suggests a diet that narrowed noticeably after deforestation"], answer: 1 }, { q: "The word \"This\" in paragraph 4 refers to _______.", options: ["the crisis-level malnutrition", "daily island life", "the popular narrative", "the narrowed diet"], answer: 3 }, { q: "What does the passage imply about how confident historians can be regarding the overall cause of Rapa Nui's population decline?", options: ["Historians agree on every aspect of the decline except the exact death toll", "The pre-contact account is well established while post-contact causes stay speculative", "Historians are fairly confident about post-contact causes but not pre-contact ones", "Radiocarbon dating shows permanent settlement likely began later than once thought"], answer: 2 }, { q: "The word \"vindicate\" in paragraph 6 is closest in meaning to _______.", options: ["justify", "excuse", "revise", "indicate"], answer: 0 }, { q: "What is the author's main purpose in writing this passage?", options: ["To explain in detail how Polynesian rats reached the island by canoe", "To argue that European colonizers bear sole responsibility for the decline", "To prove conclusively that the revisionist account is entirely correct", "To show that the popular collapse narrative is more contested than assumed"], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Both camps, notably, draw on the very same sediment core data to reach their opposing conclusions.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
  ] },
  { id: "rd-153", num: 153, title: "Đề 153", timeMin: 60, parts: [
    { title: "What Shared Hobbies Reveal About Friendship Groups", paragraphs: ["Many people assume that close friendships grow mainly out of shared beliefs or years of personal history. Yet everyday observation points to something far more ordinary: a common hobby. Groups that form around a shared activity, whether weekend cycling, amateur baking, or board games, often stay together longer than groups that come together for almost any other reason. The activity itself gives members an easy, low-pressure reason to keep meeting, long after the original spark that first brought them together has faded.", "Researchers who study social groups have noticed a simple pattern behind this durability: regular, low-stakes contact. When people meet every week to do the same activity, they build a routine that does not depend on remembering to text or plan; the calendar does the work for them. This steady contact also creates a shared identity, such as \"the running club\" or \"the book group,\" that members can mention to others, which strengthens their sense of belonging. The activity comes first; the friendship follows, deepening slowly, side by side, while attention stays on the task rather than on each other.", "This pattern differs from friendships formed at work or school, which are shaped by mandatory attendance rather than free choice. A colleague you must see every day is not the same as a teammate you have chosen to meet on a Saturday morning. Because hobby groups are voluntary, the friendships inside them tend to carry less resentment and more genuine enjoyment; nobody is required to show up, so showing up itself becomes a small, repeated signal of goodwill. Some researchers argue that this voluntary quality, not the hobby itself, is the real ingredient that makes these friendships last; without it , even the most enjoyable shared activity can start to feel like just another obligation.", "These benefits come with a quieter cost. Hobby groups can become so comfortable that they resist new members, especially once inside jokes and unwritten rules have built up over time. A newcomer who does not yet understand the group's habits may feel like an outsider even while being physically present at every session. Longstanding members, meanwhile, may mistake familiarity for agreement, assuming that because everyone shares a hobby, they also share similar opinions on unrelated matters, an assumption that is rarely tested and even more rarely true.", "None of this means people should avoid joining hobby-based groups; the opposite is closer to the truth. It simply means that the same routine which makes these friendships so reliable can also make them narrow if members never make room for anyone new. A little deliberate openness, organizers suggest, keeps the comfort of routine from quietly turning into a closed circle. The friendships that last longest, in other words, tend to be the ones that stay easy to join as well as easy to keep."], questions: [{ q: "What is the main idea of the passage?", options: ["Weekly meeting schedules alone explain why hobby friendships endure.", "Shared hobbies create durable friendships mainly through routine, low-pressure contact.", "Hobby groups mainly create closed circles that resist new members.", "Any group activity guarantees friendships stronger than family relationships."], answer: 1 }, { q: "According to the passage, what allows hobby groups to keep meeting without needing to plan?", options: ["The recurring schedule removes the need for extra planning.", "The shared identity members get from the group's name.", "A single organizer who reminds everyone individually each week.", "Deep conversation from the very first meeting together."], answer: 0 }, { q: "Based on the passage, how do hobby-based friendships typically differ from friendships formed at work?", options: ["They involve seeing a colleague every single day.", "They depend on inside jokes built up over years.", "They require the same mandatory scheduling as school.", "They begin by free choice rather than required attendance."], answer: 3 }, { q: "What does the passage say can happen to longstanding members of a hobby group?", options: ["They may resist letting any new members join.", "They may mistake shared familiarity for shared opinions.", "They usually test their assumptions against newcomers' opinions.", "They begin treating newcomers the same as old friends."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a feature of hobby-based friendship groups?", options: ["A formal leadership structure that assigns roles", "A shared identity used to describe the group", "Voluntary participation instead of obligation", "Resistance to accepting new members"], answer: 0 }, { q: "The word \"routine\" in paragraph 2 is closest in meaning to _______.", options: ["strict schedule", "close friendship", "boring habit", "regular pattern"], answer: 3 }, { q: "The word \"resentment\" in paragraph 3 is closest in meaning to _______.", options: ["bitterness", "hatred", "excitement", "resignation"], answer: 0 }, { q: "The word \"it\" in paragraph 3 refers to _______.", options: ["the hobby itself", "voluntary quality", "the real ingredient", "mandatory attendance"], answer: 1 }, { q: "What can be inferred from the passage about newcomers to a hobby group?", options: ["They will naturally be accepted once they attend enough sessions.", "Their unfamiliarity causes the group to change its habits.", "They may need deliberate effort from others to feel included.", "Longstanding members share similar opinions on unrelated matters."], answer: 2 }, { q: "What is the author's overall attitude toward hobby-based friendship groups?", options: ["Appreciative, while cautioning against unintentional exclusivity.", "Focused only on explaining research methods.", "Strongly critical of all group activities.", "Neutral and purely descriptive throughout."], answer: 0 }] },
    { title: "Vietnamese Coffee and the Weight of an Unlikely History", paragraphs: ["Few beverages carry as much unresolved history in a single cup as Vietnamese coffee. What tourists now sip as a pleasant novelty, thick, sweet, poured over ice, took shape under conditions its modern fans rarely stop to consider: colonial plantations, forced labor quotas, and a crop nobody in the region had originally asked to grow.", "French colonists introduced coffee to Vietnam in the mid-nineteenth century, initially experimenting with the arabica variety before robusta proved far better suited to the region's soil and climate. Robusta, however, is generally considered less refined in flavor than arabica, which meant Vietnamese coffee entered the global market already carrying something of an inferiority label it would spend the next century trying to shed. Plantation labor, meanwhile, was organized around production quotas that left little room for negotiation, and workers who fell short faced conditions historians now describe as exploitative rather than merely strict.", "Coffee production nearly collapsed during the decades of war that followed independence, as fields were abandoned or destroyed and the infrastructure needed to process and export beans fell apart. It was not until the Doi Moi economic reforms of 1986, reforms aimed broadly at agriculture and industry rather than coffee specifically, that cultivation quietly began to recover, expanding first in the Central Highlands before spreading further. Within roughly two decades, Vietnam had gone from a marginal producer to the world's second-largest coffee exporter, a rise that surprised even agricultural economists who had been tracking the sector.", "The distinctive practice of sweetening coffee with condensed milk likely emerged from necessity rather than preference: fresh milk was difficult to keep without reliable refrigeration, while canned condensed milk survived the tropical climate far better. Some historians suggest this substitution shaped Vietnamese taste so thoroughly that condensed milk is now treated less as a substitute than as a defining ingredient in its own right, though this claim remains difficult to verify given the scarcity of detailed household records from the period. What began as an improvised workaround gradually hardened into a national preference that shows little sign of fading.", "Today, Vietnamese robusta forms the backbone of much of the world's instant coffee supply, a role that generates enormous export volume but does little to build a reputation for quality among specialty roasters. In response, a smaller domestic movement has begun cultivating arabica at higher altitudes and marketing single-origin robusta as a distinct, defensible category rather than an inferior substitute, an effort that has met with mixed success internationally. Whether this rebranding can meaningfully shift decades of perception is not yet settled, though early results in specialty markets abroad have been described as cautiously promising.", "Viewed this way, a glass of ca phe sua da sold today carries more than caffeine and sugar. It carries the residue of a crop planted under coercion , rescued by a policy shift aimed at something else entirely, and reshaped by a dairy substitute born of climate rather than culinary ambition. None of that history is visible in the glass itself, which is perhaps exactly why it survives: the drink asks nothing of the person holding it except that they enjoy it."], questions: [{ q: "What is the main idea of the passage?", options: ["Robusta only replaced arabica because of Vietnam's soil conditions.", "Vietnam's coffee industry now prioritizes quality over export volume.", "Vietnamese coffee's modern identity reflects a layered, often coercive history.", "Every Southeast Asian coffee industry shares this same colonial history."], answer: 2 }, { q: "According to the passage, why did robusta eventually replace arabica in Vietnam?", options: ["It was better suited to local soil and climate.", "It generated an inferiority label in global markets.", "French colonists preferred robusta for its lower shipping cost.", "Workers demanded a switch away from arabica cultivation."], answer: 0 }, { q: "What prompted the recovery of Vietnam's coffee sector after decades of decline?", options: ["The expansion of cultivation into the Central Highlands.", "Direct government investment targeted specifically at coffee exporters.", "The end of the war restored plantations immediately.", "Broad economic reforms not specifically aimed at coffee."], answer: 3 }, { q: "Based on the passage, what role does Vietnamese robusta play in the world coffee market today?", options: ["It is now marketed as a distinct specialty category.", "It supplies much of the world's instant coffee.", "It has replaced arabica as the industry's quality standard.", "It is grown mainly at high mountain altitudes."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor in the history of Vietnamese coffee?", options: ["A government ban on robusta cultivation nationwide", "Strict, non-negotiable production quotas", "A national reform program launched in 1986", "A domestic shift toward higher-altitude arabica"], answer: 0 }, { q: "The word \"exploitative\" in paragraph 2 is closest in meaning to _______.", options: ["somewhat strict", "highly profitable", "abusive", "exploratory"], answer: 2 }, { q: "The word \"coercion\" in paragraph 6 is closest in meaning to _______.", options: ["gentle persuasion", "compulsion", "financial investment", "coordination"], answer: 1 }, { q: "The phrase \"this substitution\" in paragraph 4 refers to _______.", options: ["tropical climate", "canned condensed milk", "reliable refrigeration", "sweetening with condensed milk"], answer: 3 }, { q: "What can be inferred from the passage about the global reputation of Vietnamese coffee?", options: ["Its reputation may still be recovering from robusta's early quality perception.", "Its reputation has now fully caught up with top arabica producers.", "Poor global reputation caused Vietnam to switch from arabica to robusta.", "Robusta supplies a large share of the world's instant coffee."], answer: 0 }, { q: "What is the author's overall attitude toward the popularity of Vietnamese iced coffee today?", options: ["Focused narrowly on describing agricultural export statistics.", "Reflective, emphasizing the hidden history behind a simple drink.", "Dismissive of Vietnamese coffee's international reputation.", "Critical of consumers who enjoy the drink casually."], answer: 1 }] },
    { title: "Video Games and the Contested Boundaries of Art", paragraphs: ["Although several major museums have staged retrospectives devoted to video games, whether the medium qualifies as art in any traditionally rigorous sense remains far from settled outside curatorial circles, complicated by an underlying dispute over which criterion should even be doing the evaluative work. Some critics insist that interactivity itself disqualifies games from the category, since an artwork's meaning cannot be authored if the audience may alter its unfolding; others regard that objection as a failure to update inherited definitions built for static media.", "The most-cited version of this skepticism, voiced two decades ago by a prominent film critic, held that because games are won or lost according to rules set by their designers, they cannot achieve the authorial control that painting or literature routinely exercises. Defenders of games as art have never fully rebutted this so much as reframed it: rule-bound choice, they argue, is not the opposite of authored meaning but a distinct mechanism for producing it, closer to how a sonnet's fixed form shapes rather than prevents a poet's intent.", "This reframing works more comfortably for narrative-driven titles, which borrow structural tools from cinema and literature, than for abstractly formal games built around little more than spatial puzzles or reflex timing; defenders of the latter category face a harder task, since appeals to authored meaning ring thinner when a game's content is, quite literally, an arrangement of falling blocks. Yet even here some theorists locate aesthetic value not in represented content but in the felt structure of decision-making itself, treating the player's moment-to-moment choices as the artwork's real material.", "Commercial pressure complicates the picture further, though its effect is not straightforwardly corrosive : a medium financed through mass sales might be expected to drift toward formulaic safety, yet the same commercial infrastructure has, somewhat counterintuitively, subsidized large-budget productions ambitious enough to be discussed seriously alongside prestige cinema. Whether this counts as evidence that markets and artistic ambition can coexist, or merely as a survivorship story ignoring everything the market declined to fund, may say more about a critic's priors than about games themselves.", "Institutional recognition has arrived unevenly. A small number of design-focused museums now hold permanent game collections, typically justified on design-historical rather than purely aesthetic grounds, treating games as significant artifacts of interaction design regardless of any settled verdict on their status as fine art. This framing sidesteps the interactivity objection altogether, since design history has never required that an object be authored in the singular, closed sense demanded of a painting; a chair earns a place in design history without needing to resolve whether it is also sculpture.", "None of this fully resolves the original impasse , and it may be a mistake to expect resolution at all. [1] Definitions of art have historically expanded only after sustained institutional pressure rather than philosophical consensus, which suggests the current disagreement may dissolve through gradual acceptance rather than a decisive argument. [2] Photography faced strikingly similar objections a century earlier, dismissed by many contemporaries as a mechanical process incapable of the intentionality that painting required. [3] What ultimately shifted the consensus, historians generally agree, was not a single rebuttal but decades of accumulated practice that made the objection feel increasingly beside the point. [4] Video games, still barely half a century old, may simply be earlier in that same slow process."], questions: [{ q: "What is the main idea of the passage?", options: ["The interactivity objection alone has permanently disqualified video games from serious artistic consideration.", "Whether games qualify as art depends on which evaluative criterion is applied.", "Commercial funding has already resolved the dispute in games' favor.", "Museums alone can settle any medium's artistic status."], answer: 1 }, { q: "According to the passage, why do some critics believe interactivity disqualifies games from being considered art?", options: ["Games are typically financed through mass commercial sales to a broad audience.", "Museums have not yet built permanent collections devoted to games.", "Game designers rarely intend their rules to shape meaning.", "Interactivity prevents an artwork's meaning from being authored."], answer: 3 }, { q: "Based on the passage, why do design-focused museums avoid the interactivity objection when collecting video games?", options: ["They classify games as design artifacts rather than requiring singular authorship.", "They only collect games that were commercially unsuccessful in the mass market.", "They require that a game's narrative resemble literature before acquiring it.", "They have concluded that the interactivity objection is factually mistaken."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a reason video games might be compared to photography's earlier struggle for recognition as art?", options: ["Both were initially dismissed as incapable of genuine intentionality.", "Definitions of art have historically shifted through accumulated practice, not one argument.", "Photography, like games, was financed primarily through government subsidy.", "The current disagreement over games may dissolve gradually rather than through decisive proof."], answer: 2 }, { q: "The word \"corrosive\" in paragraph 4 is closest in meaning to _______.", options: ["profitable", "damaging", "surprising", "temporary"], answer: 1 }, { q: "The word \"impasse\" in paragraph 6 is closest in meaning to _______.", options: ["deadlock", "agreement", "discovery", "framework"], answer: 0 }, { q: "The phrase \"This reframing\" in paragraph 3 refers to _______.", options: ["rule-bound choice itself", "a sonnet's fixed form", "authored meaning alone", "producing authored meaning"], answer: 3 }, { q: "What can be inferred from the passage about games built around abstract, non-narrative content, such as puzzle mechanics?", options: ["They are widely regarded as being far easier to defend as legitimate art.", "They have already been fully accepted into every design-history museum collection worldwide.", "Their claim to status rests on a different kind of argument.", "Critics agree they lack any aesthetic value at all."], answer: 2 }, { q: "What is the author's overall attitude toward the debate over whether video games are art?", options: ["Focused narrowly on cataloguing the technical history of interaction design rather than aesthetics.", "Measured, treating the dispute as unresolved and shaped by differing assumptions.", "Strongly critical of every attempt to defend games as art.", "Certain that funding alone settles the question."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? \"That parallel is imperfect, since photography's objection concerned mechanical reproduction rather than interactivity, but the underlying pattern of resistance followed by gradual acceptance remains instructive.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "What Freedom Is For: Competing Goals Behind the Idea of Liberty", paragraphs: ["Not only do most political traditions claim to value freedom, but the very disagreements that divide them turn out, on inspection, to be disagreements about what freedom is actually for. Two broad answers have dominated Western political thought since the mid-twentieth century: one holds that liberty consists chiefly in the absence of external interference, while the other insists that freedom is meaningless without the practical capacity to act on one's choices.", "The first view, often labeled negative liberty, treats coercion by others, rather than mere circumstance, as the relevant obstacle; a person prevented from traveling by poverty is, on this account, unfree only in a loose or metaphorical sense, since no one has forcibly stopped them. Critics of this framing do not necessarily dispute its internal logic so much as its usefulness, arguing that a definition of freedom indifferent to whether people can actually exercise it risks becoming, in practice if not in principle, an argument for leaving existing inequalities undisturbed.", "The second view, positive liberty, shifts the relevant question from whether one is interfered with to whether one is actually self-governing, capable of translating intention into action rather than merely being left alone to fail. Taken to its logical end, however, this framing invites a genuinely uncomfortable possibility: if freedom requires the capacity for rational self-mastery, then someone judged incapable of exercising that capacity might, on certain readings, be said to require guidance toward interests they do not yet recognize as their own.", "This is not a merely theoretical worry. Twentieth-century political theorists pointed to precisely this reasoning as the intellectual scaffolding beneath regimes that justified coercion in the name of liberating citizens from their own supposedly false consciousness, a maneuver that converts freedom's positive sense from an emancipatory ideal into a license for its opposite. Defenders of positive liberty typically respond that this slide is not inevitable but contingent on abandoning the individual's own judgment as the final authority on personal interests, a safeguard the original formulations were never intended to discard.", "A third framework, associated with republican political theory, attempts to sidestep this quarrel by relocating the threat: what matters, on this view, is not whether interference actually occurs but whether it could occur arbitrarily, at another's discretion, regardless of whether that discretion is ever exercised. A servant with an unusually generous master remains unfree in the republican sense, since the master's forbearance is a matter of will rather than right, and could be withdrawn at any moment without violating anyone's stated rules.", "Which of these three pictures should govern practical politics is not a question that abstract argument alone is likely to settle, if only because each framework was constructed, at least in part, to make certain policy conclusions look conceptually necessary rather than merely preferred. Debates over welfare provision, for instance, are rarely fought at the level of economic evidence alone; they are just as often, if less visibly, disputes about which of these three goals liberty is ultimately supposed to serve, and no amount of empirical data can adjudicate a disagreement that is conceptual before it is practical.", "None of the three traditions has managed to fully absorb the others' central objection, and it is at least arguable that none ever will, since each begins from a different intuition about what unfreedom most fundamentally consists of. What can be said with more confidence is that invoking freedom without specifying which of these goals is meant settles nothing on its own, however persuasive the word may sound in isolation."], questions: [{ q: "What is the main idea of the passage?", options: ["Republican political theory has definitively resolved the tension between negative and positive liberty.", "Disputes about freedom are ultimately disagreements about which goal liberty should serve.", "Freedom is fundamentally an economic concept best resolved through empirical evidence.", "Negative liberty alone offers a coherent definition of freedom."], answer: 1 }, { q: "According to the passage, how does negative liberty treat a person prevented from traveling by poverty?", options: ["As entirely free in every meaningful sense, since poverty involves no coercion.", "As unfree in the same way as someone physically imprisoned.", "As a case negative liberty explicitly refuses to address.", "As unfree only in a loose, non-literal sense."], answer: 3 }, { q: "Based on the passage, what danger do critics associate with taking positive liberty to its logical end?", options: ["It could justify guiding people toward interests they do not yet recognize.", "It could eliminate coercion from political theory entirely.", "It could make external interference the sole measure of unfreedom.", "It could reduce liberty to a purely economic transaction."], answer: 0 }, { q: "According to the passage, what distinguishes republican liberty from the negative and positive views?", options: ["It rejects the idea that discretion or arbitrary power bears on freedom.", "It treats a generous master's forbearance as sufficient proof of freedom.", "It focuses on whether interference could occur arbitrarily at all.", "It defines freedom solely by financial self-sufficiency."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a framework for understanding liberty?", options: ["A view centered on freedom from external interference.", "A view centered on the practical capacity for self-governance.", "A view centered on the absence of possible arbitrary interference.", "A view centered exclusively on freedom as economic productivity."], answer: 3 }, { q: "The word \"contingent\" in paragraph 4 is closest in meaning to _______.", options: ["guaranteed", "dependent", "irrelevant", "permanent"], answer: 1 }, { q: "The word \"forbearance\" in paragraph 5 is closest in meaning to _______.", options: ["restraint", "punishment", "negotiation", "dependence"], answer: 0 }, { q: "The phrase \"this slide\" in paragraph 4 refers to _______.", options: ["citizens' false consciousness", "liberty turning coercive", "the original formulations", "abandoning individual judgment"], answer: 1 }, { q: "What can be inferred from the passage about why debates over welfare provision resist resolution through economic evidence alone?", options: ["Economic evidence about welfare policy does not yet reliably exist in sufficient quantity.", "All three theories of liberty happen to reach identical policy conclusions.", "Such debates are ultimately conceptual, not purely empirical, disputes about liberty's goal.", "Welfare provision is unrelated to any of the frameworks."], answer: 2 }, { q: "What is the author's overall attitude toward the three competing theories of liberty?", options: ["Dismissive, treating all three traditions as historically outdated and entirely irrelevant today.", "Even-handed, presenting each framework's logic without endorsing one as correct.", "Strongly persuaded republican liberty resolves the shortcomings of the other two.", "Indifferent, since the distinctions carry no consequence."], answer: 1 }] },
  ] },
  { id: "rd-160", num: 160, title: "Đề 160", timeMin: 60, parts: [
    { title: "A Spoon: How a Small Food Blog Became a Trusted Voice", paragraphs: ["When a home cook in a small kitchen first began posting recipes online, few people expected the site to grow into anything beyond a personal hobby. There was no advertising budget, no professional photography equipment, and no clear plan for building an audience. What the blog did have, from its earliest posts, was a consistent habit of testing each recipe multiple times before publishing it, a practice that would later become the site's defining feature.", "In the beginning, most posts were short and simple, often just a recipe with a few personal notes about family meals. Readers who found the site tended to return not because of clever writing, but because the recipes reliably worked. A cake that was supposed to rise did rise; a sauce that was supposed to thicken did thicken. This dependability , while unglamorous, built a small but loyal readership over the first two years.", "As more readers left comments describing problems they had encountered, the blog began responding directly to those comments and updating recipes based on what readers reported. If several people mentioned that a dish turned out too salty, the recipe was adjusted and republished with a note explaining the change. This willingness to revise publicly, rather than defend the original version, set the blog apart from many competitors who rarely updated older content.", "Growth accelerated once search engines began ranking the site highly for common cooking questions. New visitors arriving from a single search often stayed to browse other recipes, and many eventually subscribed to receive new posts by email. The blog's writer resisted pressure to post constantly, choosing instead to publish fewer recipes but to test each one more carefully, even as competitors published daily and grew their numbers faster in the short term.", "Today, the blog is frequently cited by other food writers and occasionally by professional chefs discussing home cooking techniques. Its slow, careful growth stands in contrast to many food sites that expanded quickly through frequent posting and paid promotion. The site's story suggests that, at least in cooking content, consistent reliability can matter more than speed or volume in building lasting trust with an audience."], questions: [{ q: "According to the passage, what was the blog's defining feature from its earliest posts?", options: ["Professional photography equipment used for every recipe.", "Repeatedly testing every recipe prior to publication.", "A large advertising budget spent on early promotion.", "Daily posting of new recipes from the very first month."], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Why professional photography is essential for a food blog's success.", "Building a loyal readership through reliable, well-tested content.", "Why search engine rankings are the most important factor for any blog.", "How competing food blogs eventually forced the site to post more frequently."], answer: 1 }, { q: "The word \"dependability\" in paragraph 2 is closest in meaning to _______.", options: ["reliability", "popularity", "creativity", "simplicity"], answer: 0 }, { q: "According to the passage, what did the blog do when readers reported a recipe problem?", options: ["It removed the recipe from the site permanently.", "It ignored the comments to avoid changing published content.", "It adjusted and republished the recipe with a note explaining the change.", "It asked readers to submit their own corrected version instead."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a reason the blog grew its readership?", options: ["Recipes that reliably worked when readers tried them.", "High rankings in search engine results for cooking questions.", "A willingness to publicly revise recipes based on reader feedback.", "A paid advertising campaign launched during its second year."], answer: 3 }, { q: "The phrase \"this willingness\" in paragraph 3 refers to _______.", options: ["the habit of testing recipes twice", "the practice of revising recipes publicly", "the decision to post daily", "the choice to hire a professional photographer"], answer: 1 }, { q: "According to the passage, what choice did the blog's writer make despite competitors growing faster in the short term?", options: ["To publish fewer recipes but test each one more carefully.", "To stop accepting new subscribers once traffic became too high.", "To hire additional writers to increase the posting schedule.", "To remove older recipes to make room for newer content."], answer: 0 }, { q: "What can be inferred about why the blog is now cited by professional chefs?", options: ["Professional chefs are contractually required to mention popular food blogs.", "The blog paid chefs to mention it in their own publications.", "Its reputation for careful, reliable recipes likely earned it credibility over time.", "Chefs primarily cite it because of its frequent daily posting schedule."], answer: 2 }, { q: "The word \"accelerated\" in paragraph 4 is closest in meaning to _______.", options: ["sped up", "slowed down", "stopped", "reversed"], answer: 0 }, { q: "What is the author's overall attitude toward the blog's slow, careful approach to growth?", options: ["Critical, arguing the slow pace unnecessarily limited its potential audience.", "Indifferent, treating the growth strategy as unrelated to its later success.", "Approving, presenting the careful approach as the reason for its lasting trust.", "Doubtful, suggesting the approach only worked due to lucky timing."], answer: 2 }] },
    { title: "Leonardo da Vinci and the Myth of the Solitary Genius", paragraphs: ["Leonardo da Vinci is frequently held up as the archetype of the solitary genius, a singular mind working in isolation to produce achievements no collaborator could have meaningfully contributed to. This image, appealing as it is, sits uneasily against the historical record of how Renaissance workshops actually functioned, and against Leonardo's own documented working habits, which relied far more on collaborative and institutional structures than the popular myth allows.", "Leonardo trained, like most artists of his era, within a workshop system, apprenticed as a young man to the sculptor and painter Andrea del Verrocchio in Florence. Workshop training of this kind was not a preliminary stage that a true genius quickly outgrew; it was the primary mechanism through which technical knowledge — pigment preparation, anatomical study, perspective technique — was transmitted across generations of artists. Several details in Leonardo's early paintings, in fact, are now attributed by some scholars to other hands working alongside him in Verrocchio's studio, a claim that remains debated but is no longer dismissed outright.", "Later in his career, Leonardo maintained his own workshop, in which assistants and students carried out substantial portions of commissioned work under his direction. This arrangement was standard practice at the time, not a departure from it, and it means that a meaningful share of what circulates today as \"Leonardo's output\" reflects collective workshop labor organized, but not always executed in every stroke, by Leonardo himself.", "Leonardo's scientific and engineering notebooks complicate the solitary-genius image differently. While the notebooks were indeed compiled largely through his own individual observation and experimentation, his ideas developed in continuous conversation with contemporaries — mathematicians, anatomists, and military engineers whose own work he studied, annotated, and occasionally borrowed from without always crediting the source, a common practice among Renaissance scholars rather than a personal failing unique to him.", "None of this is meant to diminish Leonardo's individual talent, which by any reasonable measure was extraordinary. The point, rather, is that extraordinary talent operated within, and was substantially enabled by, an institutional and social infrastructure — patrons who funded his work, workshops that trained him and later extended his output, and a broader intellectual community that supplied him with ideas as much as he supplied it with his own.", "Reassessing Leonardo in this light does not produce a smaller figure but a more accurately situated one. The myth of solitary genius, applied to Leonardo or to any comparably celebrated historical figure, tends to obscure exactly the kind of collaborative infrastructure that made sustained achievement at that scale possible in the first place — an infrastructure worth understanding on its own terms, rather than erasing in favor of a more dramatic individual story."], questions: [{ q: "What is the passage mainly about?", options: ["How Leonardo da Vinci's scientific notebooks were compiled and later published.", "How Leonardo's achievements relied on collaborative structures the solitary-genius myth obscures.", "Why Andrea del Verrocchio deserves more credit than Leonardo for early paintings.", "Why patrons in the Renaissance period rarely funded ambitious artistic projects."], answer: 1 }, { q: "According to the passage, what was the workshop training system primarily used for?", options: ["It served mainly as an early screening process to identify future patrons.", "It existed only to house apprentices until they found independent work.", "It transmitted technical knowledge across generations of artists.", "It was primarily a legal requirement imposed by local governments."], answer: 2 }, { q: "The word \"transmitted\" in paragraph 2 is closest in meaning to _______.", options: ["passed on", "concealed", "invented", "discarded"], answer: 0 }, { q: "What pattern connects Leonardo's early training and his later career as a workshop leader?", options: ["Both periods show Leonardo working in complete isolation from other artists.", "Both periods occurred after Leonardo had already achieved widespread fame.", "Both periods show collaborative labor shaping work later attributed mainly to Leonardo alone.", "Both periods involved Leonardo rejecting standard workshop practices of his era."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of the infrastructure that enabled Leonardo's achievements?", options: ["Patrons who funded his work.", "Workshops that trained him and extended his output.", "A broader intellectual community that supplied him with ideas.", "Formal academic degrees awarded by a university."], answer: 3 }, { q: "The word \"this arrangement\" in paragraph 3 refers to _______.", options: ["Leonardo's apprenticeship under Verrocchio", "assistants carrying out commissioned work under Leonardo's direction", "Leonardo's habit of annotating other scholars' notebooks", "the patronage system that funded Renaissance artists"], answer: 1 }, { q: "What can be inferred about Leonardo's practice of borrowing ideas from contemporaries without always crediting them?", options: ["It was widely regarded at the time as a serious ethical violation unique to Leonardo.", "It reflected a common scholarly practice of the period rather than a personal flaw.", "It was discovered only recently and significantly damaged his historical reputation.", "It occurred only in his scientific notebooks and never in his artistic work."], answer: 1 }, { q: "What is the author's purpose in stating that Leonardo's talent was \"by any reasonable measure extraordinary\" in paragraph 5?", options: ["To contradict the passage's earlier argument about collaborative infrastructure.", "To clarify that reassessing Leonardo's context does not deny his individual ability.", "To argue that Leonardo's talent has been significantly overstated by historians.", "To suggest that talent alone, without institutional support, explains his success."], answer: 1 }, { q: "The word \"situated\" in paragraph 6 is closest in meaning to _______.", options: ["contextualized", "diminished", "exaggerated", "isolated"], answer: 0 }, { q: "What is the author's overall attitude toward the solitary-genius narrative applied to historical figures like Leonardo?", options: ["Fully supportive, viewing it as an accurate reflection of how genius operates.", "Critical, as it hides the essential collaborative structures behind achievement.", "Indifferent, treating the narrative as harmless regardless of its accuracy.", "Uncertain, offering no clear evaluation of the narrative's accuracy."], answer: 1 }] },
    { title: "Genetically Modified Crops: Beyond the Safety Debate", paragraphs: ["Public debate over genetically modified crops has, for more than two decades, centered almost exclusively on a single question: are they safe to eat? Repeated systematic reviews have returned a consistent answer — currently approved GM crops present no greater health risk than their conventional counterparts — yet the debate persists largely unchanged, as though scientific consensus on safety were the only variable capable of settling controversy. What this narrow framing obscures, however, is that safety was never the primary source of resistance for many of the debate's most engaged critics.", "Intellectual property arrangements sit at the center of concerns rarely covered with the same intensity as safety. Because genetically modified seed traits are patented, farmers who purchase them typically sign licensing agreements prohibiting seed-saving, a practice that had been standard agricultural behavior for millennia before patented seed became widespread. Violating these agreements, even inadvertently through cross-pollination from a neighboring field, has in documented cases exposed farmers to legal liability, regardless of whether the farmer intentionally acquired the patented trait.", "Compounding this concern is significant consolidation within the seed industry itself. A small number of agrochemical companies now control a disproportionate share of the global commercial seed market, a concentration that predates genetic modification but has arguably accelerated alongside it, since patent protection creates barriers to entry that favor firms with substantial legal and research infrastructure over smaller competitors.", "Agronomically, the picture is more mixed than either side of the safety debate typically acknowledges. Certain GM traits — pest resistance built directly into a plant's genome, for instance — have measurably reduced pesticide application in some regions. Widespread adoption of herbicide-tolerant varieties, however, has in several documented cases accelerated the evolution of herbicide-resistant weeds, a trade-off that complicates any simple narrative of GM crops as an unqualified agronomic improvement.", "Regulatory treatment of GM crops also varies considerably across jurisdictions, and this variation carries consequences well beyond any single country's borders. [1] A shipment approved in one market may be rejected in another, disrupting trade relationships that took years to establish. [2] These disruptions fall disproportionately on smaller agricultural exporters, who typically lack the resources to navigate divergent regulatory requirements as easily as larger, vertically integrated producers can. [3] Some trade analysts argue this regulatory fragmentation, more than any consumer safety concern, now functions as the primary barrier to expanded GM crop adoption globally. [4]", "For smallholder farmers in lower-income countries, the calculus is further complicated by dependency concerns. Adopting patented seed often means committing to annual purchases from a single supplier, replacing a traditionally self-sufficient practice with a recurring financial obligation — a shift that may improve yields in good years while introducing new vulnerability in years when purchasing power is constrained.", "None of this is meant to reopen the safety question, which the available scientific evidence addresses with reasonable clarity. It is meant instead to suggest that a debate fixated on safety, however scientifically productive that particular consensus has been, has left considerably less examined the economic, legal, and agronomic questions that arguably shape the lived experience of GM crop adoption more directly than safety ever did."], questions: [{ q: "According to the passage, what does a licensing agreement typically prohibit farmers from doing?", options: ["Selling their farmland to competing agribusiness companies.", "Saving seed from patented GM crops for replanting.", "Applying pesticides recommended by the seed company.", "Planting more than one GM variety per season."], answer: 1 }, { q: "What is the main idea of the passage?", options: ["How patent lawsuits have destroyed small farms across multiple continents.", "How herbicide-resistant weeds have become the central concern of the GM crop debate.", "How a safety-focused GM crop debate obscures more consequential economic and legal questions.", "How GM crops have uniformly harmed farmers in every country worldwide."], answer: 2 }, { q: "The word \"consolidation\" in paragraph 3 is closest in meaning to _______.", options: ["concentration", "division", "regulation", "expansion"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a consequence of regulatory variation across jurisdictions?", options: ["It has disrupted trade relationships built over several years.", "It has increased consumer prices for GM-derived food products.", "It has placed a disproportionate burden on smaller exporters.", "It functions, some analysts argue, as a major barrier to adoption."], answer: 1 }, { q: "The word \"it\" in paragraph 3 refers to _______.", options: ["seed patenting", "the seed industry", "genetic modification", "pesticide application"], answer: 2 }, { q: "What trade-off is common to both herbicide-resistant weed evolution and smallholder seed dependency?", options: ["Both trade-offs were resolved entirely once GM crops were approved.", "Both trade-offs occurred only in countries with weak regulatory systems.", "Both trade-offs were predicted accurately before any GM crop was planted.", "Both trade-offs show a short-term benefit accompanied by a longer-term vulnerability."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Even minor differences in approved trait lists can trigger these rejections.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "What can be inferred about the relationship between regulatory fragmentation and consumer safety concerns in limiting GM crop adoption?", options: ["Regulatory fragmentation has entirely replaced safety concerns as a scientific research topic.", "Safety concerns arose specifically because of earlier trade disruptions between countries.", "Some analysts believe regulatory fragmentation, not safety, is now the larger barrier to adoption.", "A shipment approved in one market may be rejected in another."], answer: 2 }, { q: "The word \"disproportionately\" in paragraph 5 is closest in meaning to _______.", options: ["unevenly", "equally", "rarely", "legally"], answer: 0 }, { q: "What is the author's purpose in the final paragraph?", options: ["To argue that GM crops are unsafe despite the existing scientific consensus.", "To dismiss economic and legal concerns as ultimately unimportant.", "To highlight neglected economic, legal, and agronomic aspects.", "To announce new safety research findings not previously available."], answer: 2 }] },
    { title: "The Vitamin D Argument Against Sunscreen: Why Dermatologists Remain Unconvinced", paragraphs: ["Among the many pieces of health advice circulating online, few generate as much friction between popular intuition and professional consensus as the claim that regular sunscreen use causes vitamin D deficiency. The underlying mechanism is not fabricated — ultraviolet B radiation genuinely triggers vitamin D synthesis in skin, and sunscreen genuinely absorbs or reflects a portion of that radiation — yet dermatologists overwhelmingly reject the conclusion drawn from these two accurate premises, a disagreement that says less about the biology involved than about how that biology plays out under real-world conditions.", "In laboratory conditions, sunscreen with a sufficiently high sun protection factor, applied at the thickness used in testing, can reduce UVB-driven vitamin D synthesis substantially. This laboratory finding is frequently cited as though it settled the practical question, but the testing protocol behind SPF ratings assumes an application thickness — roughly two milligrams per square centimeter of skin — that survey data suggests few users actually achieve outside a laboratory setting.", "Observational studies examining real-world sunscreen users complicate the picture further. Several such studies have found no significant difference in vitamin D levels between regular sunscreen users and non-users, a result that would be difficult to explain if sunscreen reliably blocked vitamin D synthesis at the levels people typically apply it. Some researchers caution against over-reading these studies, however, since sunscreen users and non-users may obscure a real underlying effect through other differing behaviors — total time spent outdoors, dietary vitamin D intake, or supplement use — rather than disproving one.", "Dermatologists' rejection of the deficiency claim rests only partly on this observational evidence. Even granting that sunscreen use might modestly reduce vitamin D synthesis under some real-world conditions, the field's position is that unprotected sun exposure carries a clearer and better-established harm — cumulative skin cancer risk — than the comparatively uncertain and, where it exists, generally correctable harm of mildly suppressed vitamin D synthesis. Supplementation and dietary intake, unlike skin cancer, can address a vitamin D shortfall directly and without any accompanying carcinogenic exposure.", "This position, however, does not claim the underlying mechanism is entirely without consequence for every population. Individuals who already receive minimal sun exposure — due to indoor occupations, limited mobility, or living at high latitudes with weak seasonal UVB — may face a genuinely elevated risk of insufficient vitamin D synthesis if near-total, year-round sunscreen use were layered on top of already limited exposure, though robust evidence isolating sunscreen specifically as the decisive variable in these populations remains thin. Similarly, individuals with more heavily pigmented skin require substantially longer UVB exposure to synthesize equivalent vitamin D, which some researchers argue deserves more targeted study than it has so far received, independent of the broader sunscreen debate.", "What emerges from this evidence, then, is neither a confirmation nor a dismissal of the popular claim but something more conditional: the mechanism linking sunscreen to reduced vitamin D synthesis is real in principle, becomes measurable mainly under application conditions most users do not replicate, and may carry genuine clinical weight only for specific subgroups whose baseline sun exposure or skin pigmentation already elevates their deficiency risk independent of sunscreen use at all.", "Public health messaging built around this nuance is, unsurprisingly, harder to communicate than either a flat denial or a flat confirmation would be. [1] Dermatologists have largely opted for a specific, layered recommendation rather than a single blanket statement. [2] Sun protection is advised consistently across the general population, dietary or supplemental vitamin D is recommended as the default correction where levels run low, and closer individual monitoring is suggested specifically for the subgroups whose risk profile plausibly differs from the general case. [3] Whether this layered message survives simplification into shareable health content online is, so far, an open question the evidence itself cannot answer. [4]"], questions: [{ q: "What is the main idea of the passage?", options: ["Laboratory SPF testing protocols measure UVB blocking inaccurately.", "Sunscreen's link to vitamin D deficiency is real but often overstated.", "Dermatologists reject the deficiency claim solely due to skin cancer risk.", "Sunscreen has zero effect on vitamin D synthesis in any population."], answer: 1 }, { q: "Why might laboratory findings on sunscreen and vitamin D synthesis not directly predict real-world outcomes?", options: ["Real users rarely apply sunscreen as thickly as laboratory testing assumes.", "Laboratory testing underestimates how much sunscreen blocks UVB radiation.", "Real-world users apply sunscreen more thickly than laboratory protocols require.", "Vitamin D levels were measured incorrectly in all laboratory studies."], answer: 0 }, { q: "The word \"obscure\" in paragraph 3 is closest in meaning to _______.", options: ["reveal", "mask", "measure", "create"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor that could differ between sunscreen users and non-users in observational studies?", options: ["Total time spent outdoors by each participant.", "Dietary vitamin D intake among participants.", "Genetic variation in vitamin D receptor sensitivity.", "Use of vitamin D supplements among participants."], answer: 2 }, { q: "The word \"it\" in paragraph 2 refers to _______.", options: ["the SPF rating", "the testing protocol", "the practical question", "this laboratory finding"], answer: 3 }, { q: "According to the passage, what does the passage say about individuals with minimal baseline sun exposure who also use sunscreen year-round?", options: ["They face a certain, well-documented risk directly caused by sunscreen alone.", "They may face a genuinely elevated risk, though decisive evidence remains thin.", "They face no elevated risk regardless of their exposure levels.", "Robust evidence has already isolated sunscreen as the primary cause in this group."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This does not mean the recommendation collapses into vague generalities, however.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "What can be inferred about why dermatologists continue recommending sunscreen broadly despite acknowledging a real synthesis-reducing mechanism?", options: ["Sunscreen has been proven to have absolutely no effect on vitamin D synthesis in anyone.", "Vitamin D deficiency was found to directly cause higher skin cancer rates.", "High-SPF sunscreen can substantially reduce UVB-driven synthesis under laboratory conditions.", "Preventing skin cancer outweighs the manageable risk of vitamin D deficiency."], answer: 3 }, { q: "The word \"layered\" in paragraph 7 is closest in meaning to _______.", options: ["multi-part", "single", "outdated", "simplified"], answer: 0 }, { q: "What is the author's overall stance toward the popular claim that sunscreen causes vitamin D deficiency?", options: ["Dismissive, treating the claim as entirely baseless with no real mechanism.", "Fully supportive of the claim exactly as it circulates online.", "Indifferent, offering no evaluation of the claim's merit at all.", "Balanced, considering the claim partially valid but exaggerated in practice."], answer: 3 }] },
  ] },
];
